    private static android.graphics.Rect screenBounds(View view){int[] xy=new int[2];view.getLocationOnScreen(xy);return new android.graphics.Rect(xy[0],xy[1],xy[0]+view.getWidth(),xy[1]+view.getHeight());}
    private static int faceInk(View view){android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(128,96,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.drawable.Drawable face=view.getBackground();android.graphics.Rect original=new android.graphics.Rect(face.getBounds());face.setBounds(0,0,128,96);face.draw(new android.graphics.Canvas(image));int result=image.getPixel(64,60);face.setBounds(original);image.recycle();return result;}
    @Before public void before()throws Exception{DeviceSupport.clear();DeviceSupport.permission();}
    @Test public void allSkinsKeepMenuStructureOriginalTransparentBrandAndPersist()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).putString("language","nl").commit();
            try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
                final android.graphics.Rect[] homeBrand={null};
                scenario.onActivity(a->{assertEquals(theme,ThemeSkin.active.id);assertEquals(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,a.getRequestedOrientation());a.showHome();android.graphics.Bitmap scanner=(android.graphics.Bitmap)DeviceSupport.get(new UiArt.ScannerMark(a),"art");assertTrue("Scanner artwork has real alpha",scanner.hasAlpha());for(int resource:ReferenceArt.HOME){android.graphics.Bitmap icon=ReferenceArt.bitmap(a,resource);assertTrue("Detailed icon ships at high resolution",icon.getWidth()>=512);assertEquals("Icon has no opaque background",0,android.graphics.Color.alpha(icon.getPixel(0,0)));}assertEquals(0,android.graphics.Color.alpha(scanner.getPixel(0,0)));assertNotNull(DeviceSupport.tag(a.getWindow().getDecorView(),"reference-home"));});DeviceSupport.shot(scenario,"build3-theme-home-"+theme);scenario.onActivity(a->homeBrand[0]=screenBounds(DeviceSupport.tag(a.getWindow().getDecorView(),"home-brand")));
                scenario.onActivity(a->{a.chooseScan();assertNotNull(a.scanWizard);});DeviceSupport.shot(scenario,"build3-theme-scan-menu-"+theme);scenario.onActivity(a->{a.scanWizard.dispose();a.scanWizard=null;});
                scenario.onActivity(a->{a.showSettings();View decor=a.getWindow().getDecorView();assertNotNull(DeviceSupport.tag(decor,"language"));assertNotNull(DeviceSupport.tag(decor,"themes"));assertEquals(a.themeName(theme),((TextView)DeviceSupport.tag(decor,"selected-theme-name")).getText().toString());for(String tag:new String[]{"language","themes","about"}){LinearLayout card=(LinearLayout)DeviceSupport.tag(decor,tag);int ink=((UiArt.Magic)card.getChildAt(0)).tint;int expected=tag.equals("language")?0xff00e1ff:tag.equals("themes")?0xffd276ff:0xffffbc31;if(theme.equals("light"))expected=UiArt.mix(expected,ThemeSkin.LIGHT.text,.22f);assertEquals("Shared icon colour "+tag,expected,ink);}assertNotNull(DeviceSupport.tag(decor,"about"));assertNull(DeviceSupport.tag(decor,"scanner-settings"));assertNull(DeviceSupport.tag(decor,"document-settings"));View brand=DeviceSupport.tag(decor,"theme-brand");assertNotNull(brand);assertNull(brand.getBackground());assertEquals(0,brand.getElevation(),0);assertTrue(brand.getContentDescription().toString().contains(theme.equals("translumina")?"Translumina":"Blue Medical"));android.graphics.Bitmap logo=android.graphics.BitmapFactory.decodeResource(a.getResources(),com.bmd.scanner.R.drawable.blue_medical_logo),transparent=android.graphics.Bitmap.createBitmap(logo.getWidth(),logo.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);try{android.graphics.Paint paint=new android.graphics.Paint(3);paint.setColorFilter(ThemeSkin.active.brandFilter());new android.graphics.Canvas(transparent).drawBitmap(logo,0,0,paint);assertEquals("Transparent outside logo",0,android.graphics.Color.alpha(transparent.getPixel(0,0)));assertEquals("White source matte must disappear",0,android.graphics.Color.alpha(transparent.getPixel(700,200)));int visible=0;for(int y=0;y<logo.getHeight();y+=3)for(int x=0;x<logo.getWidth();x+=3)if(android.graphics.Color.alpha(transparent.getPixel(x,y))>240)visible++;assertTrue("Logo lettering must remain visible",visible>1000);}finally{logo.recycle();transparent.recycle();}});DeviceSupport.shot(scenario,"build3-theme-settings-"+theme);scenario.onActivity(a->{View root=a.getWindow().getDecorView();assertEquals("Home and Settings logo position and size",homeBrand[0],screenBounds(DeviceSupport.tag(root,"theme-brand")));if(theme.equals("translumina")){int blue=faceInk(DeviceSupport.tag(root,"language")),purple=faceInk(DeviceSupport.tag(root,"themes")),orange=faceInk(DeviceSupport.tag(root,"about"));assertTrue("Language stays blue on red Translumina",android.graphics.Color.blue(blue)>android.graphics.Color.red(blue)+40);assertTrue("Themes stays purple on red Translumina",android.graphics.Color.blue(purple)>android.graphics.Color.green(purple)+40&&android.graphics.Color.red(purple)>android.graphics.Color.green(purple)+15);assertTrue("About stays amber/orange on red Translumina",android.graphics.Color.red(orange)>android.graphics.Color.blue(orange)+40);}});
                scenario.recreate();scenario.onActivity(a->{assertEquals(theme,ThemeSkin.active.id);a.themes();android.app.Dialog dialog=(android.app.Dialog)DeviceSupport.get(a,"dialog");android.view.ViewGroup themeGrid=(android.view.ViewGroup)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-wheel");String[] order={"bmd","translumina","lime","violet","dark"};for(int i=0;i<order.length;i++)assertEquals("Requested theme order", "theme-"+order[i],themeGrid.getChildAt(i).getTag());for(String id:ThemeSkin.IDS){assertNotNull(DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-"+id));assertNotNull(DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-icon-"+id));}assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-bmd")).getText().toString().startsWith("Blauw"));assertEquals("Rood",((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-translumina")).getText().toString());assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-dark")).getText().toString().startsWith("Donker"));assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-lime")).getText().toString().startsWith("Groen"));assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-violet")).getText().toString().startsWith("Paars"));});DeviceSupport.shot(scenario,"build3-theme-picker-"+theme);scenario.onActivity(a->((android.app.Dialog)DeviceSupport.get(a,"dialog")).dismiss());
            }
        }
    }
    private static void selectedBadge(View root,String selected){
        int count=0;for(String id:ThemeSkin.IDS){View choice=DeviceSupport.tag(root,"theme-"+id);assertNotNull(choice);assertEquals(id.equals(selected),choice.isSelected());if(choice.isSelected())count++;assertNull("Old checkmark removed",DeviceSupport.tag(root,"theme-check-"+id));}
        assertEquals(1,count);assertEquals(selected,DeviceSupport.tag(root,"theme-selected-icon").getContentDescription().toString());
    }
    @Test public void wheelCancelsPersistsAndMigratesRemovedLightTheme()throws Exception{
        DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme","light").putString("language","nl").commit();
        try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
            scenario.onActivity(a->{assertEquals("bmd",ThemeSkin.active.id);assertEquals("bmd",a.getPreferences(0).getString("colourTheme",""));a.showSettings();a.themes();});SystemClock.sleep(400);
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();selectedBadge(root,"bmd");assertNull(DeviceSupport.tag(root,"theme-light"));DeviceSupport.tag(root,"theme-violet").performClick();selectedBadge(root,"violet");assertEquals("bmd",a.getPreferences(0).getString("colourTheme",""));d.dismiss();});SystemClock.sleep(260);
            scenario.onActivity(MainActivity::themes);SystemClock.sleep(350);scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");selectedBadge(d.getWindow().getDecorView(),"bmd");DeviceSupport.tag(d.getWindow().getDecorView(),"theme-lime").performClick();DeviceSupport.tag(d.getWindow().getDecorView(),"theme-apply").performClick();});SystemClock.sleep(600);InstrumentationRegistry.getInstrumentation().waitForIdleSync();
            scenario.onActivity(a->{assertEquals("lime",ThemeSkin.active.id);assertEquals("lime",a.getPreferences(0).getString("colourTheme",""));a.showSettings();assertEquals("Groen",((TextView)DeviceSupport.tag(a.getWindow().getDecorView(),"selected-theme-name")).getText().toString());});
        }
    }
    @Test public void selectingThemePreviewsPageSurfaceButtonAndOrbitBeforeApplyAndXReverts()throws Exception{
        for(String language:new String[]{"nl","ar"}){
            DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme","bmd").putString("language",language).commit();
            try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
                scenario.onActivity(a->{a.showSettings();a.themes();});SystemClock.sleep(400);
                java.util.Set<Integer> surfaces=new java.util.HashSet<>(),buttons=new java.util.HashSet<>();
                for(String theme:ThemeSkin.IDS){
                    scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();DeviceSupport.tag(root,"theme-"+theme).performClick();assertSame("The same picker stays open",d,DeviceSupport.get(a,"dialog"));assertTrue(d.isShowing());if(android.animation.ValueAnimator.areAnimatorsEnabled()){assertEquals("Requested palette duration",650L,((android.animation.ValueAnimator)DeviceSupport.get(d,"paletteAnimation")).getDuration());assertEquals("Requested rotation duration",650L,((ChoicePicker.Layout)DeviceSupport.tag(root,"theme-wheel")).trail.getDuration());}assertEquals("Page previews immediately",theme,ThemeSkin.active.id);assertEquals("Preview is not saved","bmd",a.getPreferences(0).getString("colourTheme",""));assertEquals(language,a.getPreferences(0).getString("language",""));assertEquals(a.themeName(theme),((TextView)DeviceSupport.tag(a.getWindow().getDecorView(),"selected-theme-name")).getText().toString());});
                    SystemClock.sleep(850);InstrumentationRegistry.getInstrumentation().waitForIdleSync();
                    scenario.onActivity(a->{ChoicePicker d=(ChoicePicker)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();surfaces.add(faceInk(d.panel));buttons.add(faceInk(d.apply));assertEquals("Selected name follows the new accent",ThemeSkin.forId(theme).accent,((TextView)DeviceSupport.tag(root,"theme-name-"+theme)).getCurrentTextColor());selectedBadge(root,theme);});
                    DeviceSupport.shot(scenario,"build4121-live-theme-"+language+"-"+theme);
                }
                assertEquals("All five surfaces visibly change",5,surfaces.size());assertEquals("All five Apply buttons visibly change",5,buttons.size());
                scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();DeviceSupport.tag(root,"theme-translumina").performClick();DeviceSupport.tag(root,"theme-violet").performClick();DeviceSupport.tag(root,"picker-close").performClick();});SystemClock.sleep(400);InstrumentationRegistry.getInstrumentation().waitForIdleSync();
                scenario.onActivity(a->{assertEquals("X restores the prior palette","bmd",ThemeSkin.active.id);assertEquals("bmd",a.getPreferences(0).getString("colourTheme",""));assertEquals(a.themeName("bmd"),((TextView)DeviceSupport.tag(a.getWindow().getDecorView(),"selected-theme-name")).getText().toString());});
                scenario.recreate();scenario.onActivity(a->{assertEquals("bmd",ThemeSkin.active.id);assertEquals(language,a.getPreferences(0).getString("language",""));});
            }
        }
    }
    @Test public void choosingAnyLanguageImmediatelyTranslatesHeadingAndApplyBeforeSaving()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).putString("language","nl").commit();
            try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
                scenario.onActivity(a->{a.showSettings();a.languages();});
                for(int n=0;n<MainActivity.LANGS.length;n++){final int index=n;scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();android.view.ViewGroup choices=(android.view.ViewGroup)DeviceSupport.tag(root,"language-options");choices.getChildAt(index).performClick();assertSame("Language preview keeps the same picker open",d,DeviceSupport.get(a,"dialog"));assertTrue("Picker remains attached while Settings translates",d.isShowing());if(MainActivity.LANGS[index].equals("el"))assertEquals("Ρυθμίσεις",a.s("settings"));if(MainActivity.LANGS[index].equals("zh"))assertEquals("设置",a.s("settings"));assertEquals(a.s("choose_language"),((TextView)DeviceSupport.tag(root,"sheet-title")).getText().toString());assertEquals(a.s("apply"),((TextView)DeviceSupport.tag(root,"language-apply")).getText().toString());assertEquals(a.themeName(theme),((TextView)DeviceSupport.tag(a.getWindow().getDecorView(),"selected-theme-name")).getText().toString());assertEquals("nl",a.getSharedPreferences("MainActivity",0).getString("language",""));if(index==1)assertEquals("Apply",((TextView)DeviceSupport.tag(root,"language-apply")).getText().toString());});}
                scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");ViewGroup choices=(ViewGroup)DeviceSupport.tag(d.getWindow().getDecorView(),"language-options");choices.getChildAt(1).performClick();});DeviceSupport.shot(scenario,"build3-theme-english-preview-"+theme);
                scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-apply").performClick();assertEquals("en",a.getSharedPreferences("MainActivity",0).getString("language",""));});SystemClock.sleep(300);InstrumentationRegistry.getInstrumentation().waitForIdleSync();scenario.onActivity(a->assertTrue("Settings must rebuild in English after dismissal",DeviceSupport.hasText(a.getWindow().getDecorView(),"Theme")));scenario.onActivity(a->{a.themes();android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");assertTrue(((TextView)DeviceSupport.tag(d.getWindow().getDecorView(),"theme-name-dark")).getText().toString().startsWith("Dark"));d.dismiss();});
            }
        }
    }
    @Test public void fifteenFlagsFitAndArabicSwitchesDirectionWithoutChangingProductCodes()throws Exception{
        try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
            scenario.onActivity(a->{a.showSettings();a.languages();});SystemClock.sleep(400);
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();ViewGroup flags=(ViewGroup)DeviceSupport.tag(root,"language-options");assertEquals(15,MainActivity.LANGS.length);assertArrayEquals(new String[]{"hi","ar","zh"},java.util.Arrays.copyOfRange(MainActivity.LANGS,12,15));assertEquals("el",MainActivity.LANGS[9]);for(String language:MainActivity.LANGS){View choice=DeviceSupport.tag(root,"language-"+language);assertNotNull(choice);android.graphics.Rect bounds=screenBounds(choice);assertTrue(bounds.width()>=44*a.getResources().getDisplayMetrics().density);assertTrue(bounds.left>=0&&bounds.right<=a.getResources().getDisplayMetrics().widthPixels);assertTrue(bounds.top>=0&&bounds.bottom<=a.getResources().getDisplayMetrics().heightPixels);}for(int i=0;i<15;i++)for(int j=i+1;j<15;j++)assertFalse("Flag tap targets do not overlap",android.graphics.Rect.intersects(screenBounds(flags.getChildAt(i)),screenBounds(flags.getChildAt(j))));DeviceSupport.tag(root,"language-ar").performClick();assertEquals(View.LAYOUT_DIRECTION_RTL,((ChoicePicker)d).panel.getLayoutDirection());assertEquals(a.s("choose_language"),((TextView)DeviceSupport.tag(root,"sheet-title")).getText().toString());assertEquals("nl",a.getPreferences(0).getString("language","nl"));});DeviceSupport.shot(scenario,"build412-language-arabic");
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-el").performClick();});DeviceSupport.shot(scenario,"build412-language-greek");
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-zh").performClick();});DeviceSupport.shot(scenario,"build412-language-mandarin");
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-ro").performClick();});DeviceSupport.shot(scenario,"build412-language-romanian");
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-pl").performClick();});DeviceSupport.shot(scenario,"build412-language-polish");
            scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-apply").performClick();});SystemClock.sleep(300);scenario.recreate();scenario.onActivity(a->{assertEquals("pl",a.getPreferences(0).getString("language",""));assertEquals("Ustawienia",a.s("settings"));});
        }
    }
    @Test public void nativeZoomAnimatesInEveryPaletteAndCameraAloneMayRotate()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).commit();DeviceSupport.context().getSharedPreferences("BoxScanActivity",0).edit().clear().commit();
            try(ActivityScenario<BoxScanActivity> scenario=ActivityScenario.launch(new Intent(DeviceSupport.context(),BoxScanActivity.class).putExtra("language","nl"))){UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());DeviceSupport.startBoxWizard(scenario,"box","13");SystemClock.sleep(250);scenario.onActivity(a->DeviceSupport.call(a,"cameraPage",new Class<?>[]{}));long deadline=SystemClock.elapsedRealtime()+35000;AtomicBoolean ready=new AtomicBoolean();while(SystemClock.elapsedRealtime()<deadline){scenario.onActivity(a->ready.set((Boolean)DeviceSupport.get(a,"ready")));if(ready.get())break;SystemClock.sleep(150);}assertTrue("Camera must bind",ready.get());scenario.onActivity(a->{if(a.markerPopup!=null)a.markerPopup.close();});SystemClock.sleep(500);
                scenario.onActivity(a->{View root=a.getWindow().getDecorView();assertEquals(ActivityInfo.SCREEN_ORIENTATION_FULL_SENSOR,a.getRequestedOrientation());assertNull(DeviceSupport.tag(root,"theme-brand"));assertEquals(4,((android.view.ViewGroup)DeviceSupport.tag(root,"box-toolbar")).getChildCount());assertTrue(DeviceSupport.tag(root,"box-shutter") instanceof ScannerControls.PhotoStep);assertNotNull(DeviceSupport.tag(root,"box-back"));View viewport=DeviceSupport.tag(root,"box-camera-viewport");assertEquals(0,viewport.getTop());assertEquals(((View)viewport.getParent()).getHeight(),viewport.getHeight());assertNull(DeviceSupport.tag(root,"horizontal-zoom"));assertNotNull(a.pinchZoom);assertNotNull(DeviceSupport.tag(root,"scanner-dock"));assertEquals(View.GONE,DeviceSupport.tag(root,"pinch-zoom-ratio").getVisibility());assertTrue(a.session.tracker.items().isEmpty());});DeviceSupport.shot(null,"build3-theme-camera-"+theme);if(theme.equals("bmd")){scenario.onActivity(a->{ScannerControls.Torch lamp=(ScannerControls.Torch)DeviceSupport.tag(a.getWindow().getDecorView(),"box-flash");lamp.state(true,true);});DeviceSupport.shot(null,"build3-lamp-on-control-preview");scenario.onActivity(a->{ScannerControls.Torch lamp=(ScannerControls.Torch)DeviceSupport.tag(a.getWindow().getDecorView(),"box-flash");lamp.state(false,true);});DeviceSupport.shot(null,"build3-lamp-off-control-preview");}
                if(theme.equals("translumina")){scenario.onActivity(a->a.session.tracker.importCode(new ScanTracker.Detection("orientation-test-fixture","QR",.1f,.1f,.2f,.2f),0));device.unfreezeRotation();device.executeShellCommand("touch /data/local/tmp/bmd-rotate-landscape");long rotatedDeadline=SystemClock.elapsedRealtime()+20000;AtomicBoolean rotated=new AtomicBoolean();while(SystemClock.elapsedRealtime()<rotatedDeadline){scenario.onActivity(a->rotated.set(a.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE&&(Boolean)DeviceSupport.get(a,"ready")));if(rotated.get())break;SystemClock.sleep(150);}scenario.onActivity(a->android.util.Log.i("BMD-rotate","orientation="+a.getResources().getConfiguration().orientation+" ready="+DeviceSupport.get(a,"ready")+" inCamera="+DeviceSupport.get(a,"inCamera")+" requested="+a.getRequestedOrientation()+" rotation="+device.getDisplayRotation()));DeviceSupport.shot(null,"build3-rotation-check");assertTrue("Rotated camera must rebind",rotated.get());InstrumentationRegistry.getInstrumentation().waitForIdleSync();scenario.onActivity(a->{assertEquals(13,a.session.expected);assertEquals(1,a.session.tracker.items().size());assertEquals("orientation-test-fixture",a.session.tracker.items().get(0).raw);assertNotNull(DeviceSupport.tag(a.getWindow().getDecorView(),"box-camera-viewport"));assertNull(DeviceSupport.tag(a.getWindow().getDecorView(),"horizontal-zoom"));assertNotNull(a.pinchZoom);});DeviceSupport.shot(null,"build3-theme-camera-landscape");scenario.onActivity(a->a.summary());long menuDeadline=SystemClock.elapsedRealtime()+10000;AtomicBoolean portrait=new AtomicBoolean();while(SystemClock.elapsedRealtime()<menuDeadline){scenario.onActivity(a->portrait.set(a.getResources().getConfiguration().orientation==Configuration.ORIENTATION_PORTRAIT));if(portrait.get())break;SystemClock.sleep(150);}assertTrue("Menu must stay portrait with device held sideways",portrait.get());device.executeShellCommand("touch /data/local/tmp/bmd-rotate-portrait");SystemClock.sleep(1500);device.unfreezeRotation();}
                scenario.onActivity(a->{a.summary();assertEquals(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,a.getRequestedOrientation());assertEquals(13,a.session.expected);});
            }
        }
    }
